using namespace std;
​
bool found = false;
int resX = -1, resY = -1;
int n, m;
​
​
// 四个方向
vector<vector<int>> directed = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
​
// 递归回溯进行匹配
bool dfs(vector<string> & words, vector<vector<bool>> &visited, int x, int y, int index, string& targetWord) {
​
    // 越界
    if (x < 0 || y < 0 || x >= n || y >= m) {
        return false;
    }
    // 当前位置不能匹配上指定字符
    if (words[x][y] != targetWord[index]) {
        return false;
    }
    // 重复访问
    if (visited[x][y]) {
        return false;
    }
    visited[x][y] = true;
    // 完整匹配结束
    if (index == targetWord.size() - 1) {
        visited[x][y] = false;
        return true;
    }
​
    for (int i = 0; i < 4; i++) {
        int nx = x + directed[i][0];
        int ny = y + directed[i][1];
        bool flag = dfs(words, visited, nx, ny, index + 1, targetWord);
        if (flag) {
            visited[x][y] = false;
            return true;
        }

    }
    // 回溯
    visited[x][y] = false;
    return false;
}
​
​
int main() {
    cin >> n >> m;
    vector<string> words(n);
    string keyWord;
    cin >> keyWord;
    for (int i = 0; i < n; i++) {
        cin>>words[i];
    }

    vector<vector<bool>> visited(n, vector<bool>(m, false));
    for (int i = 0; i < n; i++) {
        // 找到之后尽早退出循环
        if (found) {
            break;
        }
        for (int j = 0; j < m; j++) {
            if (words[i][j] == keyWord[0]) {
                bool res = dfs(words, visited, i, j, 0, keyWord);
                if (res) {
                    found = true;
                    resX = i + 1;
                    resY = j + 1;
                    break;
                }
            }
        }
    }

    if (!found) {
        cout << "NO";
    } else {
        cout << resX << " " << resY;
    }
    return 0;
}
