import java.util.*;
​
public class Main {
    static int N, M;
    static String word;
    static char[][] grid;
    static boolean[][] visited;
    static boolean isFind = false;
​
    // 四个方向：右，下，上，左
    static int[][] DIRECTIONS = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
​
    static void backtracking(int x, int y, int wordIdx) {
        if (wordIdx == word.length() - 1) {
            isFind = true;
            return;
        }
​
        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];
​
            if (nx >= 0 && nx < N && ny >= 0 && ny < M 
                && !visited[nx][ny] 
                && grid[nx][ny] == word.charAt(wordIdx + 1)) {
                visited[nx][ny] = true;
                backtracking(nx, ny, wordIdx + 1);
                visited[nx][ny] = false;
            }
        }
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        word = sc.next();
        grid = new char[N][M];
​
        for (int i = 0; i < N; i++) {
            String row = sc.next();
            for (int j = 0; j < M; j++) {
                grid[i][j] = row.charAt(j);
            }
        }
​
        visited = new boolean[N][M];
​
        for (int i = 0; i < N && !isFind; i++) {
            for (int j = 0; j < M && !isFind; j++) {
                if (grid[i][j] == word.charAt(0)) {
                    visited[i][j] = true;
                    backtracking(i, j, 0);
                    visited[i][j] = false;
                    // 找到合法路径,直接输出当前位置
                    if (isFind) {
                        System.out.println((i + 1) + " " + (j + 1));
                        return;
                    }
                }
            }
        }
​
        if (!isFind) {
            System.out.println("NO");
        }
    }
}
