let input = [];
rl.on("line", (line) => {
    input.push(line.trim());
}).on("close", () => {
    let [N, M] = input[0].split(" ").map(Number);
    let word = input[1];
    let grid = input.slice(2, 2 + N).map(row => row.split(""));
​
    let visited = Array.from({ length: N }, () => Array(M).fill(false));
    let isFind = false;
​
    // 四个方向：右，下，上，左
    const DIRECTIONS = [[0,1],[1,0],[-1,0],[0,-1]];

    // 递归回溯寻找合法完整匹配
    function backtracking(x, y, wordIdx) {
        if (wordIdx === word.length - 1) {
            isFind = true;
            return;
        }
        // 往四个方向尝试匹配下一个字符
        for (let [dx, dy] of DIRECTIONS) {
            let nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < M &&
                !visited[nx][ny] &&
                grid[nx][ny] === word[wordIdx + 1]) {
                visited[nx][ny] = true;
                backtracking(nx, ny, wordIdx + 1);
                visited[nx][ny] = false;
            }
        }
    }
​
    for (let i = 0; i < N && !isFind; i++) {
        for (let j = 0; j < M && !isFind; j++) {
            if (grid[i][j] === word[0]) {
                visited[i][j] = true;
                backtracking(i, j, 0);
                visited[i][j] = false;
                // 找到直接输出
                if (isFind) {
                    console.log((i + 1) + " " + (j + 1));
                    return;
                }
            }
        }
    }
​
    if (!isFind) {
        console.log("NO");
    }
});
