package main
​
import (
    "bufio"
    "fmt"
    "os"
)
​
var (
    N, M   int
    word   string
    grid   [][]byte
    visited [][]bool
    isFind bool
)
​
// 四个方向：右，下，上，左
var DIRECTIONS = [][2]int{{0, 1}, {1, 0}, {-1, 0}, {0, -1}}
​
// 递归回溯寻找完整合法匹配
func backtracking(x, y, wordIdx int) {
    if wordIdx == len(word)-1 {
        isFind = true
        return
    }
    for _, d := range DIRECTIONS {
        nx, ny := x+d[0], y+d[1]
        if nx >= 0 && nx < N && ny >= 0 && ny < M &&
            !visited[nx][ny] && grid[nx][ny] == word[wordIdx+1] {
            visited[nx][ny] = true
            backtracking(nx, ny, wordIdx+1)
            visited[nx][ny] = false
        }
    }
}
​
func main() {
    in := bufio.NewReader(os.Stdin)
    fmt.Fscan(in, &N, &M)
    fmt.Fscan(in, &word)
​
    grid = make([][]byte, N)
    for i := 0; i < N; i++ {
        var row string
        fmt.Fscan(in, &row)
        grid[i] = []byte(row)
    }
​
    visited = make([][]bool, N)
    for i := 0; i < N; i++ {
        visited[i] = make([]bool, M)
    }
​
    for i := 0; i < N && !isFind; i++ {
        for j := 0; j < M && !isFind; j++ {
            if grid[i][j] == word[0] {
                visited[i][j] = true
                backtracking(i, j, 0)
                visited[i][j] = false
                // 找到合法完整匹配路径直接输出
                if isFind {
                    fmt.Println(i+1, j+1)
                    return
                }
            }
        }
    }
​
    if !isFind {
        fmt.Println("NO")
    }
}
